def filtrer(datos, prefijo):
    '''Generador: filtra por prefijo'''
    for item in datos:
        if item.startswith(prefijo):
            yield item

def transformar(datos):
    '''Generador: transforma a mayúsculas'''
    for item in datos:
        yield item.upper()

def contar(datos):
    '''Consume el generador y cuenta'''
    return sum(1 for _ in datos)

