def encontrar_duplicados(lista):
    '''Encuentra elementos duplicados en O(n)'''
    vistos = set()
    duplicados = set()
    for item in lista:
        if item in vistos:
            duplicados.add(item)
        else:
            vistos.add(item)
    return list(duplicados)

