def encontrar_duplicados_cuadratica(lista):
    '''O(n²): compara todos los pares'''
    duplicados = []
    for i in range(len(lista)):
        for j in range(i + 1, len(lista)):
            if lista[i] == lista[j] and lista[i] not in duplicados:
                duplicados.append(lista[i])
    return duplicados

def encontrar_duplicados_lineal(lista):
    '''O(n): usa set para tracking'''
    vistos = set()
    duplicados = set()
    for item in lista:
        if item in vistos:
            duplicados.add(item)
        else:
            vistos.add(item)
    return list(duplicados)

