def contar_frecuencias_cuadratica(lista):
    '''O(n²): list.count() es O(n), llamado n veces'''
    frecuencias = {}
    for item in lista:
        if item not in frecuencias:
            frecuencias[item] = lista.count(item)  # O(n)
    return frecuencias

def contar_frecuencias_lineal(lista):
    '''O(n): Counter hace una sola pasada'''
    return dict(Counter(lista))

